#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = path.join(
  root,
  "ios",
  "ChineseChronicles",
  "Resources",
  "chronicles.v1.json"
);
const destination = path.join(root, "web", "demo", "data.js");
const data = JSON.parse(fs.readFileSync(source, "utf8"));
const checkOnly = process.argv.includes("--check");

const output = [
  "// Generated by tools/build_web_demo.mjs.",
  "// The native app and this HTML demo share the same reviewed corpus.",
  `export default ${JSON.stringify(data, null, 2)};`,
  "",
].join("\n");

if (checkOnly) {
  if (!fs.existsSync(destination)) {
    console.error(`missing ${path.relative(root, destination)}`);
    process.exit(1);
  }
  if (fs.readFileSync(destination, "utf8") !== output) {
    console.error("web/demo/data.js is stale; run node tools/build_web_demo.mjs");
    process.exit(1);
  }
  console.log("web demo data is current");
} else {
  fs.writeFileSync(destination, output, "utf8");
  console.log(`wrote ${path.relative(root, destination)}`);
}
